git diff --check; git diff --stat; rg -n 'Sessions live in Postgres|keeps sessions in Postgres|0001-keep-sessions' docs; python3 - <<'PY'
import pathlib, re
broken = []
for page in pathlib.Path('docs').rglob('*.md'):
    for target in re.findall(r'\]\(([^)]+)\)', page.read_text()):
        if '://' in target or target.startswith('#'):
            continue
        if not (page.parent / target.split('#')[0]).exists():
            broken.append((str(page), target))
assert not broken, broken
print('Documentation file links resolve.')
PY

